// OpenCode entry for installs from the repository root. Each pack bundle
// under plugins/ is a complete OpenCode plugin (its index.js is generated by
// scripts/sync-plugins.sh); this entry loads the bundles listed in `bundles`.
//
// OpenCode 1.x calls every exported function as a plugin factory. OpenCode
// 2.x reads the default export's `id` and calls `setup(ctx)`.

import * as engineeringSkills from "./plugins/engineering-skills/index.js";

const bundles = [engineeringSkills];

export const plugin = async (input) => {
  const hooks = await Promise.all(bundles.map((bundle) => bundle.plugin(input)));
  return {
    config: async (cfg) => {
      for (const hook of hooks) await hook.config?.(cfg);
    },
  };
};

// OpenCode 1.x also calls `setup` as a plugin factory; it gets empty hooks.
export const setup = async (ctx) => {
  if (typeof ctx?.skill?.transform !== "function") return {};
  for (const bundle of bundles) await bundle.setup(ctx);
};

export default { id: "augments-labs-skills", server: plugin, setup };
